using ELedgerCare.Domain.Archive;
using ELedgerCare.Infrastructure.Persistence;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata;
using Xunit;

namespace ELedgerCare.Infrastructure.Tests;

/// <summary>
/// BIC-01: inspects the SQL actually generated by EF Core/Npgsql (no server needed) and the model mapping.
/// </summary>
public sealed class PersistenceMappingTests
{
    private static ELedgerCareDbContext CreateContext() => new(
        new DbContextOptionsBuilder<ELedgerCareDbContext>()
            .UseNpgsql("Host=127.0.0.1;Port=1;Database=sql_generation_only")
            .Options);

    [Fact]
    public void Metadata_projection_never_selects_original_bytes()
    {
        using var db = CreateContext();
        var key = Guid.NewGuid();

        var sql = IntakeStore.ProjectMetadata(db.Documents.Where(d => d.IdempotencyKey == key)).ToQueryString();

        Assert.Contains("byte_length", sql, StringComparison.Ordinal);
        Assert.Contains("sha256", sql, StringComparison.Ordinal);
        Assert.DoesNotContain(".bytes", sql, StringComparison.Ordinal);
        TestContext.Current.TestOutputHelper?.WriteLine(sql);
    }

    [Fact]
    public void Original_download_query_selects_only_bytes()
    {
        using var db = CreateContext();
        var id = Guid.NewGuid();

        var sql = db.OriginalArtifacts.Where(a => a.DocumentId == id).Select(a => a.Bytes).ToQueryString();

        Assert.Contains(".bytes", sql, StringComparison.Ordinal);
        Assert.DoesNotContain("sha256", sql, StringComparison.Ordinal);
    }

    [Fact]
    public void Document_summary_projection_never_selects_original_or_raw_output_bytes()
    {
        using var db = CreateContext();
        var id = Guid.NewGuid();

        var sql = ExtractionStore.ProjectDocumentSummary(db, db.Documents.Where(d => d.DocumentId == id)).ToQueryString();

        Assert.Contains("byte_length", sql, StringComparison.Ordinal);
        Assert.Contains("sha256", sql, StringComparison.Ordinal);
        Assert.Contains("page_count", sql, StringComparison.Ordinal);
        Assert.DoesNotContain(".bytes", sql, StringComparison.Ordinal);
        Assert.DoesNotContain("raw_output_bytes", sql, StringComparison.Ordinal);
        Assert.DoesNotContain("machine_snapshot_json", sql, StringComparison.Ordinal);
    }

    [Fact]
    public void Review_history_summary_projection_never_selects_field_values_or_blob_bytes()
    {
        using var db = CreateContext();
        var id = Guid.NewGuid();

        var sql = WorkOrderReviewStore.ProjectHistorySummaries(db, id).ToQueryString();

        Assert.Contains("revision_number", sql, StringComparison.Ordinal);
        Assert.Contains("unknown_field_count", sql, StringComparison.Ordinal);
        Assert.DoesNotContain("human_value", sql, StringComparison.Ordinal);
        Assert.DoesNotContain("machine_snapshot_json", sql, StringComparison.Ordinal);
        Assert.DoesNotContain("raw_output_bytes", sql, StringComparison.Ordinal);
    }

    [Fact]
    public void Archive_search_queries_never_select_original_raw_diagnostic_or_machine_snapshot_blobs()
    {
        var cursorPos = new ArchiveCursorPosition(DateTimeOffset.UtcNow, 1_794_885_000_123_456L, Guid.NewGuid());
        var sqlFragments = new List<string>
        {
            ArchiveStore.UnprojectedGuardSql,
            ArchiveStore.LoadReviewedUnitsSql,
            ArchiveStore.LoadMachineUnitsSql,
        };

        foreach (var source in new[] { ArchiveSourceFilter.All, ArchiveSourceFilter.Machine, ArchiveSourceFilter.Reviewed })
        {
            sqlFragments.Add(ArchiveStore.BuildSearchCardHeadersSql(
                new ParsedArchiveQuery(string.Empty, [], source, 20, After: null)));
            sqlFragments.Add(ArchiveStore.BuildSearchCardHeadersSql(
                new ParsedArchiveQuery("WO-004192 pump", ["WO-004192", "pump"], source, 20, After: cursorPos)));
        }

        foreach (var sql in sqlFragments)
        {
            Assert.DoesNotContain(".bytes", sql, StringComparison.OrdinalIgnoreCase);
            Assert.DoesNotContain("raw_output_bytes", sql, StringComparison.OrdinalIgnoreCase);
            Assert.DoesNotContain("diagnostic_raw_output_utf8", sql, StringComparison.OrdinalIgnoreCase);
            Assert.DoesNotContain("machine_snapshot_json", sql, StringComparison.OrdinalIgnoreCase);
            Assert.DoesNotContain("unknown_reason", sql, StringComparison.OrdinalIgnoreCase);
            Assert.DoesNotContain("operator_display_label", sql, StringComparison.OrdinalIgnoreCase);
        }

        var keywordCursorSql = ArchiveStore.BuildSearchCardHeadersSql(
            new ParsedArchiveQuery("WO-004192", ["WO-004192"], ArchiveSourceFilter.All, 20, After: cursorPos));
        Assert.Contains("ILIKE @term0 ESCAPE '\\'", keywordCursorSql, StringComparison.Ordinal);
        Assert.Contains("(d.submitted_at, d.document_id) < (@afterTs, @afterId)", keywordCursorSql, StringComparison.Ordinal);
    }

    [Fact]
    public void All_foreign_keys_restrict_deletes()
    {
        using var db = CreateContext();
        var foreignKeys = db.Model.GetEntityTypes().SelectMany(e => e.GetForeignKeys()).ToList();

        Assert.Equal(19, foreignKeys.Count);
        Assert.All(foreignKeys, fk => Assert.Equal(DeleteBehavior.Restrict, fk.DeleteBehavior));
    }
}
